def solve(data):
    packages = data['packages']
    names = sorted(packages)
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    best_vector = None
    best_versions = None

    def is_acyclic(selected):
        graph = {}
        for name, row in selected.items():
            graph[name] = [
                dep['name']
                for dep in row.get('deps', [])
                if not dep.get('feature') or dep['feature'] in features
            ]

        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, []):
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(selected, constraints):
        nonlocal best_vector, best_versions

        pending = [name for name in constraints if name not in selected]
        if not pending:
            if not is_acyclic(selected):
                return
            versions = {name: row['version'] for name, row in selected.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = min(pending)
        if name not in packages:
            return

        forbidden = blocked.get(name, ())
        pin = pins.get(name)
        for row in choose(packages[name], constraints[name]):
            version = row['version']
            if version in forbidden or (name in pins and version != pin):
                continue

            next_selected = dict(selected)
            next_selected[name] = row
            next_constraints = dict(constraints)
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dep['name']
                low, high = dep['min'], dep['max']
                if dep_name in next_constraints:
                    old_low, old_high = next_constraints[dep_name]
                    low = max(low, old_low)
                    high = min(high, old_high)
                if low > high:
                    valid = False
                    break
                next_constraints[dep_name] = (low, high)
                if (dep_name in next_selected and
                        not low <= next_selected[dep_name]['version'] <= high):
                    valid = False
                    break

            if valid:
                search(next_selected, next_constraints)

    constraints = {name: tuple(interval) for name, interval in data['roots'].items()}
    search({}, constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
